{
  "name": "builder_all_pairs_gap_weight_001",
  "intuition": "Use all valid preference pairs but weight them by the (clipped) objective gap so clearer wins contribute more while near-ties are downweighted, improving signal-to-noise and generalization.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # lower objective is better\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n\n    # Nonnegative weights based on objective gap (loser - winner), clipped to stabilize.\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    w_max = extra.get('gap_weight_max', 10.0)\n    weight = gap.clamp(min=0.0, max=w_max)\n\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'gap_weight_max': float(w_max)})\n"
}

{
  "name": "builder_all_pairs_gap_weight_001",
  "intuition": "Downweight near-ties by using a nonnegative preference weight proportional to the objective gap, so clearer improvements contribute more signal while still keeping full pair coverage.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # objective: lower is better\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Nonnegative weight; emphasize clearer wins while keeping all valid pairs.\n    scale = extra.get('gap_scale', 1.0)\n    weight = (gap / (gap + scale)).clamp_min(0.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_weight', 'gap_scale': float(scale)})\n"
}

