  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {}) if extra is not None else {}\n    alpha = float(extra.get('alpha', hp.get('alpha', 1.0))) if extra is not None else 1.0\n    scale = float(hp.get('scale', 1.6984110138845042))\n    clamp_v = float(hp.get('clamp', 15.0))\n\n    x = alpha * scale * (lpw - lpl)\n    x = ops.clamp(x, -clamp_v, clamp_v)\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        w = ops.clamp(weight, 0.0, 1e9)\n        w = ops.where(ops.isfinite(w), w, ops.zeros_like(w))\n        loss = loss * w\n\n    return loss.mean()",
