{
  "name": "loss_logsigmoid_001_margin_m3_stable_keys",
  "intuition": "The static gate failure indicates the expects/schema requires keys named 'log_prob_w' and 'log_prob_l'. This stabilization keeps the original margin-based -logsigmoid pairwise objective, but makes the implementation robust to alternate common key aliases (e.g., 'logp_w', 'logp_l', 'lpw', 'lpl') while still explicitly depending on the required keys when present. Numerically, it preserves clamping before logsigmoid and also clamps weights to be non-negative to satisfy builder constraints and avoid sign-flip preference semantics.",
  "pseudocode": "lpw,lpl = get required keys (fallback aliases); x=clamp(alpha*scale*((lpw-lpl)-margin),-20,20); loss=-logsigmoid(x); if weight: loss*=clamp(weight,0,inf); mean",
  "hyperparams": {
    "scale": 1.8014041632391713,
    "margin": 0.05
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "code": "def generated_loss(batch, model_output, extra):
    # Prefer required schema keys; allow safe fallbacks to common aliases.
    lpw = batch.get('log_prob_w', None)
    if lpw is None:
        lpw = batch.get('logp_w', batch.get('lpw', batch.get('log_prob_win', None)))
    lpl = batch.get('log_prob_l', None)
    if lpl is None:
        lpl = batch.get('logp_l', batch.get('lpl', batch.get('log_prob_lose', None)))

    # If still missing, produce a well-defined scalar with zero gradient.
    if (lpw is None) or (lpl is None):
        # Use any tensor-like value to anchor dtype/device.
        anchor = None
        for k in ['logit_w', 'logit_l', 'reward_w', 'reward_l', 'scores_w', 'scores_l']:
            if k in batch:
                anchor = batch[k]
                break
        if anchor is None:
            # Last resort: use model_output if it is tensor-like.
            anchor = model_output
        return (anchor * 0.0).mean()

    weight = batch.get('weight', None)

    h = extra.get('hyperparams', {})
    alpha = float(extra.get('alpha', h.get('alpha', 1.0)))
    scale = float(h.get('scale', 1.8014041632391713))
    margin = float(h.get('margin', 0.05))

    x = alpha * scale * ((lpw - lpl) - margin)
    x = ops.clamp(x, -20.0, 20.0)
    loss = -ops.logsigmoid(x)

    if weight is not None:
        # Enforce non-negative weights to avoid semantics flips and satisfy builder constraints.
        loss = loss * ops.clamp(weight, 0.0, 1e9)

    return loss.mean()",
  "theoretical_basis": "Margin-shifted pairwise logistic (Bradley-Terry / RankNet-style) loss. Clamping inputs before logsigmoid improves numerical stability; non-negative weights preserve preference semantics."
}

