{
  "name": "loss_logsigmoid_margin_pref_gap",
  "intuition": "The failure is a static expects-gate: the loss reads batch['log_prob_w'] and batch['log_prob_l'] but the required expects keys were not declared. Keep the same stable, monotonic preference core (-logsigmoid of a scaled winner-loser log-prob gap with clamping), and make it numerically safer by (1) clamping the gap-logit to a moderate range, and (2) using a weighted mean that normalizes by sum of weights (with eps) to avoid scale drift and NaNs when weights are present.",
  "pseudocode": "lpw = batch['log_prob_w']; lpl = batch['log_prob_l']\nd = lpw - lpl\nx = clamp(alpha*scale*(d - margin), clamp_min, clamp_max)\nper = -logsigmoid(x)\nif weight: return sum(per*weight)/ (sum(weight)+eps) else mean(per)",
  "hyperparams": {
    "scale": 1.35,
    "margin": 0.05,
    "clamp_min": -20.0,
    "clamp_max": 20.0,
    "eps": 1e-08
  },
  "operators_used": [
    "logsigmoid",
    "clamp"
  ],
  "expects": {
    "batch": [
      "log_prob_w",
      "log_prob_l"
    ],
    "optional_batch": [
      "weight"
    ],
    "extra": [
      "alpha",
      "hyperparams"
    ]
  },
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    hp = extra.get('hyperparams', {}) if extra is not None else {}\n    alpha = float(extra.get('alpha', 1.0)) if extra is not None else 1.0\n    scale = float(hp.get('scale', 1.35))\n    margin = float(hp.get('margin', 0.05))\n    cmin = float(hp.get('clamp_min', -20.0))\n    cmax = float(hp.get('clamp_max', 20.0))\n    eps = float(hp.get('eps', 1e-8))\n\n    # Pairwise preference logit with a small margin; clamp for numerical stability.\n    x = alpha * scale * ((lpw - lpl) - margin)\n    x = ops.clamp(x, cmin, cmax)\n    per_example = -ops.logsigmoid(x)\n\n    if weight is None:\n        return per_example.mean()\n\n    # Stable weighted mean (weights assumed nonnegative by builder gate).\n    wsum = ops.clamp(weight.sum(), eps, 1e30)\n    return (per_example * weight).sum() / wsum",
  "theoretical_basis": "Bradley-Terry / logistic pairwise preference loss on the winner-loser log-probability gap. Adding a small positive margin encourages separation while preserving monotonicity. Clamping the logit and using a normalized weighted mean improves numerical stability."
}

